CREATE OR REPLACE FUNCTION public.apply_import(_filename text,_updates jsonb,_creates jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE bid uuid; entry jsonb; p products; pid uuid; before_data jsonb; BEGIN IF NOT has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Yönetici gerekli'; END IF; IF jsonb_typeof(_updates) IS DISTINCT FROM 'array' OR jsonb_typeof(_creates) IS DISTINCT FROM 'array' OR jsonb_array_length(_updates)+jsonb_array_length(_creates)>10000 THEN RAISE EXCEPTION 'Geçersiz aktarım'; END IF; INSERT INTO import_batches(filename) VALUES(_filename) RETURNING id INTO bid;
FOR entry IN SELECT value FROM jsonb_array_elements(_updates) ORDER BY value->>'id' LOOP SELECT * INTO p FROM products WHERE id=(entry->>'id')::uuid FOR UPDATE; IF NOT FOUND OR p.revision IS DISTINCT FROM (entry->>'revision')::bigint THEN RAISE EXCEPTION 'Ürün değişti; dosyayı yeniden önizleyin'; END IF; before_data:=jsonb_build_object('stock',p.stock,'price',p.price); IF entry ? 'stock' THEN INSERT INTO stock_adjustments(product_id,new_stock,reason) VALUES(p.id,(entry->>'stock')::int,'Aktarım '||bid::text); END IF; IF entry ? 'price' THEN UPDATE products SET price=(entry->>'price')::numeric WHERE id=p.id; END IF; SELECT * INTO p FROM products WHERE id=p.id; INSERT INTO import_items(batch_id,product_id,previous_data,applied_data,applied_revision) VALUES(bid,p.id,before_data,jsonb_build_object('stock',p.stock,'price',p.price),p.revision); END LOOP;
FOR entry IN SELECT value FROM jsonb_array_elements(_creates) LOOP pid:=create_admin_product(jsonb_build_object('sku',entry->>'sku','name',entry->>'name','slug','import-'||gen_random_uuid()::text,'price',entry->'price'),'[]','[]','[]',(entry->>'stock')::int); SELECT * INTO p FROM products WHERE id=pid; INSERT INTO import_items(batch_id,product_id,previous_data,applied_data,applied_revision,was_created) VALUES(bid,p.id,jsonb_build_object('stock',0,'price',0),jsonb_build_object('stock',p.stock,'price',p.price),p.revision,true); END LOOP; RETURN bid; END $$;
REVOKE ALL ON FUNCTION public.apply_import(text,jsonb,jsonb) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.apply_import(text,jsonb,jsonb) TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.rollback_import(_batch_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE batch import_batches; item import_items; p products; BEGIN IF NOT has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Yönetici gerekli'; END IF; SELECT * INTO batch FROM import_batches WHERE id=_batch_id FOR UPDATE; IF NOT FOUND OR batch.rolled_back_at IS NOT NULL THEN RAISE EXCEPTION 'Aktarım bulunamadı veya zaten geri alındı'; END IF; FOR item IN SELECT * FROM import_items WHERE batch_id=_batch_id ORDER BY product_id LOOP SELECT * INTO p FROM products WHERE id=item.product_id FOR UPDATE; IF p.revision IS DISTINCT FROM item.applied_revision THEN RAISE EXCEPTION 'Sonradan işlem görmüş ürün var; geri alma durduruldu: %',p.sku; END IF; IF item.was_created AND (EXISTS(SELECT 1 FROM order_items WHERE product_id=p.id) OR EXISTS(SELECT 1 FROM purchases WHERE product_id=p.id) OR EXISTS(SELECT 1 FROM product_oem_numbers WHERE product_id=p.id) OR EXISTS(SELECT 1 FROM product_vehicles WHERE product_id=p.id) OR EXISTS(SELECT 1 FROM product_supplier_codes WHERE product_id=p.id)) THEN RAISE EXCEPTION 'Yeni ürün işlem gördüğü için geri alınamaz'; END IF; INSERT INTO stock_adjustments(product_id,new_stock,reason) VALUES(p.id,(item.previous_data->>'stock')::int,'Geri alma '||_batch_id::text); UPDATE products SET price=(item.previous_data->>'price')::numeric WHERE id=p.id; END LOOP; UPDATE import_batches SET rolled_back_at=now(),rolled_back_by=auth.uid() WHERE id=_batch_id; END $$;
REVOKE ALL ON FUNCTION public.rollback_import(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.rollback_import(uuid) TO authenticated,service_role;
CREATE POLICY "Public read referenced product photos" ON storage.objects FOR SELECT TO anon,authenticated USING(bucket_id='product-photos' AND EXISTS(SELECT 1 FROM public.products p WHERE storage.objects.name IN(p.image_url,p.image_original_url,p.image_thumbnail_url)));
CREATE INDEX products_km_natural_idx ON public.products ((nullif(btrim(sku),'') COLLATE public.km_natural),id);